program:
procedure CostumeReturnDateReminders {
  about "Remind each renter about their return date"
  policy CostumePolicy
  sheet Rentals "Rentals" { renter: Text, phone: Phone, due_back: Date, status: Text, deposit: Money, id_number: Text private }
  trigger every day at 08:30

  let all = fetch Rentals
  let due = filter all where status == "out"
  for each r in due up to 100 {
    let m = draft sms to r.phone: "Hi {r.renter}, a reminder from the shop: your return date is in a week."
    let ok = request approval of m from owner timeout 12 hours else skip
    send ok
    update r set status = "notified"
  }
  notify owner "Please update my business partner yourself."
}

